import json
M=np.asarray(Image.open('/app/target.png'))[:,:,0]<100
D=ndi.distance_transform_edt(M)
def contours(field,level):
 # Marching squares, keyed by common grid edges.
 active=field>level
 yx=np.argwhere((active[:-1,:-1]!=active[1:,:-1]) |(active[:-1,:-1]!=active[:-1,1:]) |(active[:-1,:-1]!=active[1:,1:]))
 verts={};adj={}
 def edge(key,a,b):
  if key not in verts:
   va=field[a];vb=field[b];f=(level-va)/(vb-va)
   verts[key]=np.array([a[1]+f*(b[1]-a[1]),a[0]+f*(b[0]-a[0])])
  return key
 for y,x in yx:
  corners=[(y,x),(y,x+1),(y+1,x+1),(y+1,x)]
  keys=[(0,y,x),(1,y,x+1),(0,y+1,x),(1,y,x)]
  es=[]
  for i in range(4):
   a,b=corners[i],corners[(i+1)%4]
   if active[a]!=active[b]:es.append(edge(keys[i],a,b))
  if len(es)==2:pairs=[es]
  elif len(es)==4:pairs=[es[:2],es[2:]]
  else:continue
  for a,b in pairs:adj.setdefault(a,[]).append(b);adj.setdefault(b,[]).append(a)
 unseen=set(adj);result=[]
 while unseen:
  start=next(iter(unseen));cur=start;prev=None;loop=[]
  for _ in range(len(adj)+1):
   loop.append(verts[cur]);unseen.discard(cur)
   nxt=[v for v in adj[cur] if v!=prev]
   if not nxt:break
   prev,cur=cur,nxt[0]
   if cur==start:break
  if len(loop)>8:result.append(np.array(loop))
 return result

def smooth(loop,sigma=1.5):
 q=ndi.gaussian_filter1d(loop,sigma,axis=0,mode='wrap')
 return q

def resample(q,step=.9,closed=False):
 if closed:q=np.r_[q,q[:1]]
 s=np.r_[0,np.cumsum(np.linalg.norm(np.diff(q,axis=0),axis=1))]
 if s[-1]<1e-6:return q[:1]
 t=np.linspace(0,s[-1],max(2,int(np.ceil(s[-1]/step))+1))
 return np.c_[np.interp(t,s,q[:,0]),np.interp(t,s,q[:,1])]

if __name__=='__main__':
 levels=np.arange(4.5,D.max(),5)
 loops=[]
 for lev in levels:
  cs=contours(D,lev)
  for c in cs:
   if len(c)>12:loops.append(dict(level=float(lev),q=smooth(c)))
 print('loops',len(loops),'levels',levels,'max',D.max())
 # Connect each loop to its closest parent on the preceding level.
 for i,l in enumerate(loops):
  if l['level']==levels[0]:l['parent']=None;continue
  opts=[]
  for j,p in enumerate(loops):
   if abs(p['level']-(l['level']-5))>.01:continue
   dist,idx=cKDTree(p['q']).query(l['q']);k=np.argmin(dist)
   opts.append((dist[k],j,k,idx[k]))
  if not opts:raise RuntimeError('missing parent')
  _,j,k,pk=min(opts);l.update(parent=j,join=int(k),parent_join=int(pk))
 for i,l in enumerate(loops):l['children']=[j for j,k in enumerate(loops) if k['parent']==i]
 def walk(i,start=0):
  l=loops[i];q=l['q'];n=len(q);out=[]
  kids={}
  for j in l['children']:kids.setdefault(loops[j]['parent_join'],[]).append(j)
  for ix in list(range(start,n))+list(range(start+1)):
   out.append(q[ix])
   for j in kids.get(ix,[]):
    ch=loops[j];out.extend(walk(j,ch['join']));out.append(q[ix])
  return out
 paths=[]
 for i,l in enumerate(loops):
  if l['parent'] is not None:continue
  q=l['q']; # Begin near closest interior point to keep initial contact inside.
  a=np.array(walk(i));paths.append(resample(a,step=.85))
 np.savez('/app/output/fill_paths.npz',**{f'p{i}':a for i,a in enumerate(paths)})
 im=Image.fromarray(np.where(M[:,:,None],np.array([200,200,200]),np.array([255,255,255])).astype('uint8'))
 dr=ImageDraw.Draw(im)
 for i,a in enumerate(paths):dr.line([tuple(x) for x in a],fill=['red','blue','green','orange'][i%4],width=1)
 im.save('/app/output/planned.png')
 print('roots',len(paths),'length mm',[np.linalg.norm(np.diff(a,axis=0),axis=1).sum()*.22186 for a in paths],'steps',[len(a) for a in paths])
